"""render and ats_check against golden output generated by the TS version (tests/fixtures/golden.ts)."""

import json
from pathlib import Path
from typing import Any

import pytest

from cv_tailor_py.agent import ats_check, render
from cv_tailor_py.ats import run_ats_checks
from cv_tailor_py.cli import load_profile
from cv_tailor_py.models import Education, ParsedJD, Profile, Rewritten

ROOT = Path(__file__).resolve().parent.parent
FIXTURES = ROOT / "tests" / "fixtures"
PROFILE = load_profile(ROOT / "data" / "profile.example.json")
GOLDEN: dict[str, Any] = json.loads((FIXTURES / "golden.json").read_text())
RENDER_CASES: list[dict[str, Any]] = json.loads((FIXTURES / "render_cases.json").read_text())
ATS_CASES: list[dict[str, Any]] = json.loads((FIXTURES / "ats_cases.json").read_text())


def _jd(required: list[str]) -> ParsedJD:
    return ParsedJD(role="", seniority="", required_skills=required, nice_to_have=[])


@pytest.mark.parametrize("case", RENDER_CASES, ids=lambda c: c["id"])
def test_render_matches_ts(case: dict[str, Any]) -> None:
    jd = ParsedJD.model_validate(case["jd"])
    text = Rewritten.model_validate(case["rewritten"])

    cv = render(PROFILE, list(PROFILE.roles), text, jd)

    assert cv == GOLDEN["render"][case["id"]]["cv"]


@pytest.mark.parametrize("case", RENDER_CASES, ids=lambda c: c["id"])
def test_ats_check_on_rendered_cv_matches_ts(case: dict[str, Any]) -> None:
    golden = GOLDEN["render"][case["id"]]
    jd = ParsedJD.model_validate(case["jd"])

    report = ats_check(golden["cv"], jd)

    assert report.model_dump(by_alias=True) == golden["ats"]


@pytest.mark.parametrize("case", ATS_CASES, ids=lambda c: c["id"])
def test_ats_edge_cases_match_ts(case: dict[str, Any]) -> None:
    report = run_ats_checks(case["cv"], _jd(case["requiredSkills"]))
    assert report.model_dump(by_alias=True) == GOLDEN["ats"][case["id"]]


def test_render_omits_empty_education_year() -> None:
    profile = Profile.model_validate(
        PROFILE.model_dump()
        | {"education": [Education(school="School Y", degree="Bootcamp", year="")]}
    )
    cv = render(profile, [], Rewritten(summary="s", bullets={}), _jd([]))
    assert cv.endswith("## Education\nBootcamp, School Y")


def test_render_and_ats_check_log_spans(spans: Any) -> None:
    case = RENDER_CASES[0]
    golden = GOLDEN["render"][case["id"]]
    jd = ParsedJD.model_validate(case["jd"])

    cv = render(PROFILE, list(PROFILE.roles), Rewritten.model_validate(case["rewritten"]), jd)
    ats_check(cv, jd)

    logged = {s["span_attributes"]["name"]: s for s in spans.pop()}
    assert logged["render"]["span_attributes"]["type"] == "function"
    assert logged["render"]["metrics"]["bullets"] == golden["bullets"]
    assert logged["render"]["metrics"]["cv_chars"] == golden["cvChars"]
    assert logged["render"]["output"] == golden["cv"]
    assert logged["ats_check"]["metadata"]["ats"] == golden["ats"]
